import java.text.Normalizer;
import java.util.List;
import java.util.Locale;
import java.util.Set;
import java.util.function.Predicate;
import java.util.regex.Pattern;

/**
 * Which customers a query asks for: a free-text name and a set of statuses.
 *
 * <p>A customer matches when it satisfies both parts. The name matches when every
 * whitespace-separated term appears, ignoring case and accents, in the customer's
 * first name or last name. An empty set of statuses matches every status.
 *
 * @param name     the text to look for; blank matches every name
 * @param statuses the statuses to keep; empty keeps every status
 */
public record CustomerFilter(String name, Set<CustomerStatus> statuses) {

    /** Matches every customer. */
    public static final CustomerFilter ALL = new CustomerFilter("", Set.of());

    private static final Pattern WHITESPACE = Pattern.compile("\\s+", Pattern.UNICODE_CHARACTER_CLASS);
    private static final Pattern COMBINING_MARKS = Pattern.compile("\\p{M}+");

    public CustomerFilter {
        name = (name == null) ? "" : name.strip();
        statuses = (statuses == null) ? Set.of() : Set.copyOf(statuses);
    }

    /** Returns a test for the customers this filter keeps. */
    public Predicate<Customer> asPredicate() {
        List<String> terms = termsOf(name);
        return customer -> {
            if (!statuses.isEmpty() && !statuses.contains(customer.status())) {
                return false;
            }
            String first = fold(customer.firstName());
            String last = fold(customer.lastName());
            return terms.stream().allMatch(term -> first.contains(term) || last.contains(term));
        };
    }

    private static List<String> termsOf(String text) {
        return WHITESPACE.splitAsStream(fold(text))
                .filter(term -> !term.isEmpty())
                .toList();
    }

    /** Lower-cases {@code text} and strips its accents, so that matching ignores both. */
    private static String fold(String text) {
        String decomposed = Normalizer.normalize(text, Normalizer.Form.NFD);
        return COMBINING_MARKS.matcher(decomposed).replaceAll("").toLowerCase(Locale.ROOT);
    }
}
