+import org.springframework.boot.test.context.SpringBootTest;
+import org.springframework.boot.test.web.server.LocalServerPort;
+
+/**
+ * Drives the running application in a real, headless Chromium. It needs a Chromium
+ * installed for Playwright, so it is run on its own:
+ * {@code mvn -o test -Dtest=CustomerListBrowserIT}. Plain {@code mvn test} stays
+ * browserless.
+ *
+ * <p>Some things only a browser shows: what the address bar says, and how many
+ * queries typing costs the backend.
+ */
+@SpringBootTest(webEnvironment = SpringBootTest.WebEnvironment.RANDOM_PORT)
+class CustomerListBrowserIT {
+
+    private static Playwright playwright;
+    private static Browser browser;
+
+    @LocalServerPort
+    private int port;
+
+    @Autowired
+    private QueryLog queryLog;
+
+    private Page page;
+
+    @BeforeAll
+    static void launchBrowser() {
+        playwright = Playwright.create();
+        browser = playwright.chromium().launch(new BrowserType.LaunchOptions().setHeadless(true));
+    }
+
+    @AfterAll
+    static void closeBrowser() {
+        browser.close();
+        playwright.close();
+    }
+
+    @BeforeEach
+    void openPage() {
+        page = browser.newPage();
+        queryLog.clear();
+    }
+
+    @AfterEach
+    void closePage() {
+        page.close();
