+
+    @Test
+    void openingTheListWithoutParametersShowsEverythingAndAnEmptyFilter() {
+        open("/");
+
+        assertThat(summary("Showing 500 of 500")).isVisible();
+        assertThat(nameField()).hasValue("");
+        assertEquals(null, rawQuery());
+    }
+
+    @Test
+    void openingTheListWithTheFilterInTheAddressShowsTheFilter() {
+        open("/?name=vir&status=ACTIVE,CLOSED");
+
+        assertThat(nameField()).hasValue("vir");
+        assertThat(summary("Showing 10 of 500")).isVisible();
+        assertEquals("ACTIVE,CLOSED", selectedStatuses());
+        assertEquals("name=vir&status=ACTIVE,CLOSED", rawQuery());
+    }
+
+    /**
+     * Typing narrows the list once it pauses, not on Enter or blur. A whole name costs
+     * one reload: one count query and one page query. The address bar follows, and no
+     * history entry is added for the keystrokes.
+     */
+    @Test
+    void typingNarrowsTheListWithOneReloadAndNoHistory() {
+        open("/");
+        int historyBefore = historyLength();
+        int countsBefore = queryLog.countQueries().size();
+        int pagesBefore = queryLog.pageQueries().size();
+
+        nameField().pressSequentially("mäkinen");
+
+        assertThat(summary("Showing 15 of 500")).isVisible();
+        assertEquals(1, queryLog.countQueries().size() - countsBefore, "count queries for typing");
+        assertEquals(1, queryLog.pageQueries().size() - pagesBefore, "page queries for typing");
+        assertEquals(historyBefore, historyLength(), "typing must not add history entries");
+        assertEquals("name=m%C3%A4kinen", rawQuery());
+    }
+
+    /**
+     * Slow typing, with pauses shorter than the reload delay, must not reload per
+     * keystroke. The page can stall for a moment after the first key, which may split
+     * the name into two reloads; the spec allows one or two.
+     */
+    @Test
+    void slowTypingDoesNotReloadPerKeystroke() {
+        open("/");
+        int countsBefore = queryLog.countQueries().size();
+
+        nameField().pressSequentially("mäkinen", new Locator.PressSequentiallyOptions().setDelay(150));
+
+        assertThat(summary("Showing 15 of 500")).isVisible();
+        int counts = queryLog.countQueries().size() - countsBefore;
+        assertTrue(counts <= 2, "count queries for slow typing: " + counts);
+    }
+
+    /** Statuses go into the address in declaration order, whichever was chosen first. */
+    @Test
+    void choosingStatusesUpdatesTheAddressAndClearingThemRemovesIt() {
+        open("/");
+
+        page.locator("vaadin-multi-select-combo-box input").click();
+        statusItem("CLOSED").click();
+        statusItem("ACTIVE").click();
+        assertThat(summary("Showing 333 of 500")).isVisible();
+        assertEquals("status=ACTIVE,CLOSED", rawQuery());
+
+        statusItem("CLOSED").click();
+        statusItem("ACTIVE").click();
+        assertThat(summary("Showing 500 of 500")).isVisible();
+        assertEquals(null, rawQuery());
+    }
+
+    /** A filtered address, copied and opened again, shows the same filter. */
+    @Test
+    void theAddressOfAFilteredListReopensTheSameList() {
+        open("/");
+        nameField().pressSequentially("ada aal");
+        assertThat(summary("Showing 2 of 500")).isVisible();
+        String address = page.url();
+
+        Page other = browser.newPage();
+        try {
+            other.navigate(address);
+            assertThat(other.locator("vaadin-text-field input")).hasValue("ada aal");
+            assertThat(other.getByText("Showing 2 of 500", new Page.GetByTextOptions().setExact(true)))
+                    .isVisible();
+        } finally {
+            other.close();
+        }
+    }
+
+    private void open(String path) {
+        page.navigate("http://localhost:" + port + path);
+        assertThat(page.locator("vaadin-grid")).isVisible();
+    }
+
+    private Locator nameField() {
+        return page.locator("vaadin-text-field input");
+    }
+
+    private Locator summary(String text) {
+        return page.getByText(text, new Page.GetByTextOptions().setExact(true));
+    }
+
+    private Locator statusItem(String status) {
+        return page.locator("vaadin-multi-select-combo-box-item", new Page.LocatorOptions().setHasText(status));
+    }
+
+    /** The statuses the status field has selected, sorted and comma-separated. */
+    private String selectedStatuses() {
+        return (String) page.evaluate("() => Array.from(document.querySelector('vaadin-multi-select-combo-box')"
+                + ".selectedItems, item => item.label).sort().join(',')");
+    }
+
+    private int historyLength() {
+        return ((Number) page.evaluate("window.history.length")).intValue();
+    }
+
+    /** The raw query string of the address bar, or null when there is none. */
+    private String rawQuery() {
+        return URI.create(page.url()).getRawQuery();
+    }
+}
